import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {hash,json} from './seal-simple-website-successor.mjs';
const site=process.argv[2]??'F:/VisibleMedicine/staging/20261026-atlas-keyboard-help-v2/website',out=process.argv[3]??'F:/VisibleMedicine/staging/20261026-saved-plan-react-before';assert(path.resolve(out).startsWith(path.resolve('F:/VisibleMedicine/staging')+path.sep));assert(!fs.existsSync(out));const require=createRequire(site+'/package.json'),{build}=require('esbuild');fs.mkdirSync(out);const source=`import React,{Suspense,useState,useTransition} from 'react';import{createRoot}from'react-dom/client';
import{HeadAtlasSavedStudyPlan}from './components/HeadAtlasSavedStudyPlan.tsx';
import{HEAD_MANIFEST_SHA256}from './lib/head-atlas-import.ts';
import{HEAD_STUDY_PLAN_KEY,resolveHeadStudyPlan}from './lib/head-study-plan.ts';
const entry={id:'cth.bst.pons',label:'Pons — regional mask',representation:'partial-mask',laterality:'midline_or_unpaired',mask:{file:'synthetic-only.bin',sha256:'a'.repeat(64)}};
const plan={schema:1,headRevision:HEAD_MANIFEST_SHA256,conceptIds:['brainstem-pons']};
const A={definition:{entries:[entry]}},B={definition:{entries:[]}},entries=[entry],empty=[];
if(resolveHeadStudyPlan(plan,A,HEAD_MANIFEST_SHA256,'CT').length!==1)throw Error('Synthetic plan must resolve exactly one mask entry');
const restoring=new URL(location.href).searchParams.get('case')==='restore';
if(restoring)localStorage.setItem(HEAD_STUDY_PLAN_KEY,JSON.stringify(plan));else localStorage.removeItem(HEAD_STUDY_PLAN_KEY);
window.fixture={attemptedB:0,restoredA:0,restoredB:0,key:HEAD_STUDY_PLAN_KEY,plan,restoring};
const never=new Promise(()=>{});function SuspendAfterChild({pending}){if(pending){window.fixture.attemptedB++;throw never;}return null;}
function App(){const[next,setNext]=useState(false),[pending,transition]=useTransition();
return <><header><h1>Saved plan rendering check</h1><p>Synthetic concepts only; no scan, patient, mask or account loaded.</p>
<button onClick={()=>transition(()=>setNext(true))}>Prepare suspended replacement</button><button onClick={()=>setNext(false)}>Cancel replacement</button><output data-pending>{pending?'Replacement pending':'No replacement pending'}</output></header>
<Suspense fallback={<p>Initial fallback</p>}><section data-visible-scan={next?'B':'A'}><h2>Visible synthetic scan {next?'B':'A'}</h2>
<HeadAtlasSavedStudyPlan plan={next||restoring?null:plan} entries={next||restoring?empty:entries} study={next?B:A} modality='CT' canUse={()=>true} onRestore={()=>{window.fixture[next?'restoredB':'restoredA']++;}}/>
<SuspendAfterChild pending={next}/></section></Suspense></>;}
createRoot(document.getElementById('root')).render(<App/>);`;
const b=await build({stdin:{contents:source,resolveDir:site,sourcefile:'saved-plan-real-react-fixture.tsx',loader:'tsx'},bundle:true,write:false,format:'esm',platform:'browser',jsx:'automatic',target:'es2022',metafile:true});assert.equal(b.outputFiles.length,1);fs.writeFileSync(out+'/fixture.js',b.outputFiles[0].contents,{flag:'wx'});fs.writeFileSync(out+'/index.html','<!doctype html><html lang="en"><meta charset="utf-8"><title>Synthetic saved plan render check</title><style>body{font:16px/1.5 system-ui;margin:24px;background:#f8f7f2;color:#17483f}button{margin:4px;padding:8px}button:focus-visible,summary:focus-visible{outline:3px solid #16c6b2}summary{cursor:pointer}header{margin-bottom:24px}output{display:block}</style><main id="root"></main><script type="module" src="/fixture.js"></script></html>',{flag:'wx'});
fs.writeFileSync(out+'/fixture-source.tsx.txt',source,{flag:'wx'});const inputs=Object.keys(b.metafile.inputs).filter(p=>!p.startsWith('<')&&!p.replaceAll(String.fromCharCode(92),'/').endsWith('saved-plan-real-react-fixture.tsx')).map(p=>{const f=path.resolve(site,p);return{path:f,sha256:hash(f)}});fs.writeFileSync(out+'/FIXTURE_INPUTS.json',JSON.stringify({at:new Date().toISOString(),site,actualReact:true,noApplicationModulesMocked:true,syntheticConceptOnly:true,inputs,virtualFixtureSourceSha256:hash(out+'/fixture-source.tsx.txt'),fixtureSha256:hash(out+'/fixture.js')},null,2)+'\n',{flag:'wx'});
fs.writeFileSync(out+'/serve.mjs',`import{createServer}from'node:http';import{readFileSync}from'node:fs';const base=import.meta.dirname;const files=new Map([['/','index.html'],['/fixture.js','fixture.js']]);const server=createServer((req,res)=>{const file=files.get(new URL(req.url,'http://127.0.0.1').pathname);if(!file){res.writeHead(404);res.end();return;}res.writeHead(200,{'content-type':file.endsWith('.js')?'text/javascript; charset=utf-8':'text/html; charset=utf-8','cache-control':'no-store'});res.end(readFileSync(base+'/'+file));});server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({pid:process.pid,port:server.address().port,synthetic:true})));process.stdin.setEncoding('utf8');process.stdin.on('data',t=>{if(t.trim()==='stop')server.close(()=>process.exit(0));});process.stdin.resume();\n`,{flag:'wx'});console.log(JSON.stringify({out,inputs:inputs.length,realApplicationAndReact:true}));
